D=[("수와 연산","제곱근의 뜻","√81의 값은?",["-9","9","±9","81","√9"],2),("수와 연산","근호를 포함한 식의 간단화","√12를 간단히 하면?",["√6","2√3","3√2","4√3","6"],2),("수와 연산","분모의 유리화","3/√3을 간단히 하면?",["1","√3","3√3","√6","9"],2),("다항식","다항식의 곱셈","(x + 2)(x - 3)을 전개하면?",["x² - x - 6","x² + x - 6","x² - 5x - 6","x² + 5x + 6","x² - 6"],1),("다항식","인수분해","x² - 5x + 6을 인수분해한 것은?",["(x+2)(x+3)","(x-2)(x-3)","(x-1)(x-6)","(x+2)(x-3)","(x-2)(x+3)"],2),("방정식","이차방정식","x² - 5x + 6 = 0의 해는?",["1, 6","-2, -3","2, 3","-1, -6","3만"],3),("함수","이차함수의 값","y = x²에서 x = -2일 때 y는?",["-4","-2","2","4","8"],4),("함수","이차함수의 꼭짓점","y = (x - 1)² + 2의 꼭짓점은?",["(-1,2)","(1,-2)","(1,2)","(2,1)","(-2,1)"],3),("도형","삼각비","직각삼각형에서 맞은편 변 3, 빗변 5일 때 sin θ는?",["2/5","3/5","4/5","5/3","5/2"],2),("도형","원과 접선","원의 반지름과 끝점에서 그은 접선이 이루는 각은?",["30°","45°","60°","90°","180°"],4),("도형","원주각","같은 호에 대한 중심각이 80°일 때 원주각은?",["20°","40°","80°","100°","160°"],2),("통계","평균","2, 4, 6, 8의 평균은?",["4","5","6","7","8"],2),("통계","상관관계","한 변수가 증가할수록 다른 변수도 대체로 증가하는 관계는?",["음의 상관관계","양의 상관관계","상관관계 없음","반비례","항상 같은 값"],2),("다음 단계 진입 탐색","복소수 개념 진입","허수단위 i에 대하여 i²의 값은?",["0","-1","1","i","-i"],2,True),("다음 단계 진입 탐색","행렬 덧셈 개념 진입","A=[[1,2],[3,4]], B=[[1,0],[0,1]]일 때 A+B의 왼쪽 위 성분은?",["0","1","2","3","4"],3,True)]
